// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(PayoffDefinition fuzzDefinition) public {
        // Ensure the fuzzed definition is not the same as the hardcoded default returned by the mutant
        vm.assume(!_eq(fuzzDefinition, PayoffDefinition(PayoffDefinitionLib.PayoffType.PASSTHROUGH, PayoffDefinitionLib.PayoffDirection.LONG, bytes30(0))));

        // Initialize the product with the fuzzed definition
        IProduct.ProductInfo memory info;
        info.name = "Test";
        info.symbol = "TST";
        info.oracle = IOracleProvider(address(0)); // Oracle will be validated but we need a mock that passes isContract
        info.maintenance = UFixed18.wrap(0.1e18);
        info.fundingFee = UFixed18.wrap(0);
        info.makerFee = UFixed18.wrap(0);
        info.takerFee = UFixed18.wrap(0);
        info.positionFee = UFixed18.wrap(0);
        info.makerLimit = UFixed18.wrap(1000000e18);
        info.utilizationCurve = JumpRateUtilizationCurve({
            minRate: PackedFixed18.wrap(0),
            maxRate: PackedFixed18.wrap(10e18),
            targetRate: PackedFixed18.wrap(5e18),
            targetUtilization: PackedUFixed18.wrap(0.8e18)
        });
        info.payoffDefinition = fuzzDefinition;

        // Deploy a mock oracle that supports isContract
        MockOracle oracle = new MockOracle();
        info.oracle = IOracleProvider(address(oracle));

        // Initialize the product
        c.initialize(info);

        // Check that payoffDefinition() returns the stored definition
        PayoffDefinition memory returned = c.payoffDefinition();
        assertTrue(_eq(returned, fuzzDefinition));
    }

    function _eq(PayoffDefinition memory a, PayoffDefinition memory b) private pure returns (bool) {
        return a.payoffType == b.payoffType &&
               a.payoffDirection == b.payoffDirection &&
               a.data == b.data;
    }
}

contract MockOracle {
