    // Address.isContract checks code.length > 0, so deploying this makes it a contract
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 payoffTypeUint, uint256 directionUint) public {
        // bounded: 0-2 for type, 0-1 for direction, to guarantee a valid definition
        uint8 payoffTypeRaw = uint8(payoffTypeUint % 3);
        uint8 directionRaw = uint8(directionUint % 2);

        // Build the PayoffDefinition from PayoffDefinitionLib
        PayoffDefinitionLib.PayoffType pType;
        if (payoffTypeRaw == 0) {
            pType = PayoffDefinitionLib.PayoffType.PASSTHROUGH;
        } else if (payoffTypeRaw == 1) {
            pType = PayoffDefinitionLib.PayoffType.BASIS;
        } else {
            pType = PayoffDefinitionLib.PayoffType.VANILLA;
        }

        PayoffDefinitionLib.PayoffDirection pDir =
            directionRaw == 0 ? PayoffDefinitionLib.PayoffDirection.LONG : PayoffDefinitionLib.PayoffDirection.SHORT;

        bytes30 data = bytes30(uint240(uint256(keccak256(abi.encode(block.timestamp))) >> 16));
        PayoffDefinition memory storedDef = PayoffDefinition(pType, pDir, data);

        // Initialize the product with the generated definition (all other fields as 0, minimal valid).
        // Provide a dummy oracle (zero address) - it will fail at later operations but payoffDefinition
        // is initialized and readable. Using the public initialize entry.
        IOracleProvider dummyOracle = IOracleProvider(address(0));
        IProduct.ProductInfo memory info = IProduct.ProductInfo(
            "test",
            "TST",
            storedDef,
            dummyOracle,
            UFixed18Lib.ZERO,
            UFixed18Lib.ZERO,
            UFixed18Lib.ZERO,
            UFixed18Lib.ZERO,
            UFixed18Lib.ZERO,
            UFixed18Lib.ZERO,
            JumpRateUtilizationCurve(PackedFixed18.wrap(0), PackedFixed18.wrap(0), PackedFixed18.wrap(0), PackedUFixed18.wrap(0))
        );

        // Allowed: oracle zero will pass isContract check? No, Address.isContract(0) returns false, so __UPayoffProvider__initialize reverts.
        // Provide a real oracle address -> use a minimal contract.
        // But we MUST only use public surface. Allowed: deploy a dummy oracle using a minimal helper.
        // However we cannot import anything else. We will deploy a tiny helper contract below.
        // That contract must implement IOracleProvider interface at least partially.

        // Because initialize requires msg.sender to be controller, we must prank. We'll deploy a minimal controller.
        // Because the fuzzer supplies only primitives, we must deploy the needed contracts a priori.
        vm.startPrank(address(this));
        DummyOracle oracle = new DummyOracle();
        DummyController controller = new DummyController(
            address(oracle),
            ICollateral(address(0)),
            IIncentivizer(address(0)),
            IBeacon(address(0))
        );
        vm.stopPrank();

        // Now prank the controller to initialize C.
        vm.prank(address(controller));
        c.initialize(info);

        // Read payoffDefinition after initialization
        PayoffDefinition memory actualDef = c.payoffDefinition();

        // Assert equality: the returned definition must equal the stored one.
        assertTrue(
            actualDef.payoffType == storedDef.payoffType &&
            actualDef.payoffDirection == storedDef.payoffDirection &&
            actualDef.data == storedDef.data
        );
    }
}

// Minimal helpers that implement the required interfaces just enough to pass initialization.
contract DummyOracle is IOracleProvider {
    function sync() external returns (OracleVersion memory) {
        return OracleVersion(0, 0, Fixed18.wrap(0));
    }
    function currentVersion() external view returns (OracleVersion memory) {
        return OracleVersion(0, 0, Fixed18.wrap(0));
    }
    function atVersion(uint256) external view returns (OracleVersion memory) {
        return OracleVersion(0, 0, Fixed18.wrap(0));
    }
}

