pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(bytes memory payoffData) public {
        // Create a valid PayoffDefinition with fuzzed data to initialize the contract.
        // The fuzzer explores different data bytes, and we only use actual valid data (length <= 30).
        vm.assume(payoffData.length <= 30);

        // Ensure data is exactly 30 bytes for the PayoffDefinition structure (bytes30).
        bytes30 data;
        assembly {
            data := mload(add(payoffData, 32))
        }

        // Construct the PayoffDefinition to be stored.
        PayoffDefinition memory expectedDef = PayoffDefinition(
            PayoffDefinitionLib.PayoffType.PASSTHROUGH,
            PayoffDefinitionLib.PayoffDirection.LONG,
            data
        );

        // Prepare ProductInfo to initialize the contract.
        IProduct.ProductInfo memory info;
        info.payoffDefinition = expectedDef;
        info.oracle = IOracleProvider(address(0)); // dummy, but initialization will revert if invalid
        // The other required fields are set to zero/default for simplicity;
        // they will not cause revert because initialize only uses the oracle and payoffDefinition.
        // However, UPayoffProvider.__UPayoffProvider__initialize requires oracle to be a contract address.
        // Therefore, we deploy a simple valid oracle contract.
        OracleMock oracle = new OracleMock();
        info.oracle = IOracleProvider(address(oracle));

        // Initialize the contract. Must be called by a controller contract, but we are not testing that,
        // so we prank from a mock controller that can bypass checks.
        // Since the contract expects msg.sender to be an IController, we deploy a mock controller.
        ControllerMock controller = new ControllerMock();
        vm.prank(address(controller));
        c.initialize(info);

        // Now retrieve the payoff definition.
        PayoffDefinition memory actualDef = c.payoffDefinition();

        // Assert that the returned definition exactly matches the originally stored one.
        // The reference contract returns the stored definition; the mutant returns a hard-coded one,
        // so it will fail this check for some data values.
        assertTrue(
            actualDef.payoffType == expectedDef.payoffType &&
            actualDef.payoffDirection == expectedDef.payoffDirection &&
            actualDef.data == expectedDef.data
        );
    }
}

// Minimal mock contracts required for initialization.
contract OracleMock {
    function currentVersion() external view returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion(0, 0, Fixed18.wrap(0));
    }
    function atVersion(uint256) external view returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion(0, 0, Fixed18.wrap(0));
    }
    function sync() external returns (IOracleProvider.OracleVersion memory) {
        return currentVersion();
    }
}

contract ControllerMock {
    function isProduct(IProduct) external pure returns (bool) { return true; }
    function owner(uint256) external view returns (address) { return address(0); }
    function coordinatorFor(IProduct) external pure returns (uint256) { return 0; }
    function paused() external pure returns (bool) { return false; }
    function incentivizer() external view returns (address) { return address(0); }
    function collateral() external view returns (address) { return address(0); }
    function minFundingFee() external pure returns (UFixed18) { return UFixed18.wrap(0); }
}

