pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint8 payoffType) public {
        // Restrict payoffType to valid enum values: 0, 1, 2
        vm.assume(payoffType <= 2);

        // Build a ProductInfo with an arbitrary PayoffDefinition and minimal valid parameters.
        // We must provide a valid oracle address, so deploy a minimal oracle that returns valid data.
        OracleMock oracle = new OracleMock();

        C.ProductInfo memory info = C.ProductInfo({
            name: "test",
            symbol: "TST",
            payoffDefinition: PayoffDefinition({
                payoffType: PayoffDefinitionLib.PayoffType(payoffType),
                payoffDirection: PayoffDefinitionLib.PayoffDirection.LONG,
                data: bytes30(uint240(0))
            }),
            oracle: IOracleProvider(address(oracle)),
            maintenance: UFixed18.wrap(1e17),
            fundingFee: UFixed18.wrap(1e16),
            makerFee: UFixed18.wrap(1e15),
            takerFee: UFixed18.wrap(1e15),
            positionFee: UFixed18.wrap(1e15),
            makerLimit: UFixed18.wrap(1e24),
            utilizationCurve: JumpRateUtilizationCurve({
                minRate: PackedFixed18.wrap(0),
                maxRate: PackedFixed18.wrap(1e18),
                targetRate: PackedFixed18.wrap(5e17),
                targetUtilization: PackedUFixed18.wrap(uint128(8e17))
            })
        });

        // Initialize through controller-like contract which is valid
        vm.prank(address(this));
        c.initialize(info);

        // Read back the payoff definition
        PayoffDefinition memory returnedDef = c.payoffDefinition();

        // The returned definition must match exactly what was passed during initialization
        assertTrue(
            returnedDef.payoffType == info.payoffDefinition.payoffType &&
            returnedDef.payoffDirection == info.payoffDefinition.payoffDirection &&
            returnedDef.data == info.payoffDefinition.data
        );
    }
}

// Minimal oracle mock that returns valid (non-reverting) versions to allow initialization and view calls
contract OracleMock is IOracleProvider {
    function sync() external returns (OracleVersion memory) {
        return OracleVersion(1, block.timestamp, Fixed18.wrap(1e18));
    }

    function currentVersion() external view returns (OracleVersion memory) {
        return OracleVersion(1, block.timestamp, Fixed18.wrap(1e18));
    }

    function atVersion(uint256) external pure returns (OracleVersion memory) {
        return OracleVersion(0, 0, Fixed18.wrap(0));
    }
}

