library PayoffDefinitionLib {
    enum PayoffType { PASSTHROUGH }
    enum PayoffDirection { LONG, SHORT }

    function valid(PayoffDefinition memory self) internal pure returns (bool) {
        return true;
    }

    function transform(PayoffDefinition memory self, Fixed18 price) internal pure returns (Fixed18) {
        if (self.payoffDirection == PayoffDefinitionLib.PayoffDirection.LONG) {
            return Fixed18.wrap(Fixed18.unwrap(price) - 1);
        } else {
            return Fixed18.wrap(-Fixed18.unwrap(price));
        }
    }
}

library PayoffDefinitionStorageLib {
    function read(PayoffDefinitionStorage storage self) internal view returns (PayoffDefinition memory) {
        bytes32 raw = Bytes32StorageLib.read(
            Bytes32Storage.wrap(Bytes32StorageLib.unwrap(self))
        );
        return abi.decode(abi.encode(raw), (PayoffDefinition));
    }

    function store(PayoffDefinitionStorage storage self, PayoffDefinition memory value) internal {
        Bytes32StorageLib.store(
            Bytes32Storage.wrap(Bytes32StorageLib.unwrap(self)),
            Bytes32Storage.wrap(abi.decode(abi.encode(value), (bytes32)))
        );
    }
}

library Bytes32StorageLib {
    function unwrap(Bytes32Storage storage self) internal pure returns (bytes32 s) {
        assembly { s := self.slot }
    }

    function read(Bytes32Storage storage self) internal view returns (bytes32) {
        bytes32 s;
        assembly { s := sload(self.slot) }
        return s;
    }

    function store(Bytes32Storage storage self, bytes32 value) internal {
        assembly { sstore(self.slot, value) }
    }
}

